def check_p_half():
    # Equation: 4*c1 + 2*c2 + 1*c3 = 0
    # Constraints: c_i in {-2, -1, 0, 1, 2}, not all zero

    solutions_found = False

    for c1 in [-2, -1, 0, 1, 2]:
        for c2 in [-2, -1, 0, 1, 2]:
            for c3 in [-2, -1, 0, 1, 2]:
                if c1 == 0 and c2 == 0 and c3 == 0:
                    continue

                if 4*c1 + 2*c2 + c3 == 0:
                    print(f"Solution found for p=1/2: C=({c1}, {c2}, {c3})")
                    solutions_found = True
                    # We only need to find one solution to confirm possibility
                    return solutions_found

    return solutions_found

def check_p_two():
    # Equation: 1*c1 + 2*c2 + 4*c3 = 0
    # Constraints: c_i in {-2, -1, 0, 1, 2}, not all zero

    solutions_found = False

    for c1 in [-2, -1, 0, 1, 2]:
        for c2 in [-2, -1, 0, 1, 2]:
            for c3 in [-2, -1, 0, 1, 2]:
                if c1 == 0 and c2 == 0 and c3 == 0:
                    continue

                if c1 + 2*c2 + 4*c3 == 0:
                    print(f"Solution found for p=2: C=({c1}, {c2}, {c3})")
                    solutions_found = True
                    # We only need to find one solution to confirm possibility
                    return solutions_found

    return solutions_found

